CREATE TABLE master_admin_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),enabled INTEGER NOT NULL CHECK(enabled IN(0,1)));
INSERT INTO master_admin_policy VALUES(1,0);
CREATE TABLE master_admin_binding(singleton INTEGER PRIMARY KEY CHECK(singleton=1),admin_id TEXT NOT NULL UNIQUE REFERENCES users(id),credential_id TEXT NOT NULL REFERENCES credentials(id),FOREIGN KEY(admin_id,credential_id) REFERENCES credentials(user_id,id));
CREATE VIEW valid_master_admin AS SELECT b.admin_id FROM master_admin_binding b JOIN users u ON u.id=b.admin_id JOIN user_current_credentials cc ON cc.user_id=u.id AND cc.credential_id=b.credential_id JOIN credentials c ON c.id=b.credential_id AND c.user_id=u.id JOIN admin_accounts a ON a.id=u.id WHERE u.login='master_user' AND u.kind='service' AND u.protected=1 AND u.status='active' AND c.revoked_at IS NULL AND a.username='master_user' AND a.disabled=0;
CREATE TRIGGER master_binding_insert BEFORE INSERT ON master_admin_binding BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u JOIN user_current_credentials cc ON cc.user_id=u.id JOIN credentials c ON c.id=cc.credential_id WHERE u.id=NEW.admin_id AND cc.credential_id=NEW.credential_id AND u.login='master_user' AND u.kind='service' AND u.protected=1 AND u.status='active' AND c.revoked_at IS NULL) THEN RAISE(ABORT,'invalid master binding') END; END;
CREATE TRIGGER master_binding_update BEFORE UPDATE ON master_admin_binding BEGIN SELECT RAISE(ABORT,'master binding immutable'); END;
CREATE TRIGGER master_binding_delete BEFORE DELETE ON master_admin_binding WHEN (SELECT enabled FROM master_admin_policy)=1 BEGIN SELECT RAISE(ABORT,'master binding required'); END;
CREATE TRIGGER master_policy_update BEFORE UPDATE ON master_admin_policy BEGIN SELECT CASE WHEN OLD.enabled=1 AND NEW.enabled<>1 THEN RAISE(ABORT,'master policy irreversible') END; SELECT CASE WHEN NEW.enabled=1 AND ((SELECT count(*) FROM admin_accounts)<>1 OR (SELECT count(*) FROM valid_master_admin)<>1) THEN RAISE(ABORT,'invalid master projection') END; END;
CREATE TRIGGER master_policy_delete BEFORE DELETE ON master_admin_policy BEGIN SELECT RAISE(ABORT,'master policy required'); END;
CREATE TRIGGER master_admin_insert BEFORE INSERT ON admin_accounts WHEN (SELECT enabled FROM master_admin_policy)=1 BEGIN SELECT RAISE(ABORT,'independent owner forbidden'); END;
CREATE TRIGGER master_admin_update BEFORE UPDATE ON admin_accounts WHEN (SELECT enabled FROM master_admin_policy)=1 AND (NEW.id<>OLD.id OR NEW.username<>OLD.username OR NEW.password_hash<>OLD.password_hash OR NEW.disabled<>OLD.disabled) BEGIN SELECT RAISE(ABORT,'master projection immutable'); END;
CREATE TRIGGER master_admin_delete BEFORE DELETE ON admin_accounts WHEN (SELECT enabled FROM master_admin_policy)=1 BEGIN SELECT RAISE(ABORT,'master projection required'); END;
